<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import axios from "axios";
import Swal from "sweetalert2";

const props = defineProps({ filters: { type: Object, required: true }, catalogs: { type: Object, default: () => ({}) }, capabilities: { type: Object, default: () => ({}) }, configuration: { type: Object, default: () => ({}) }, initialStatus: { type: String, default: "" }, initialCaseId: { type: [String, Number], default: null } });
const rows = ref([]); const meta = ref({}); const loading = ref(false); const error = ref(""); const selected = ref(null); const detailLoading = ref(false); const activeForm = ref("");
const local = reactive({ search: "", status: props.initialStatus || "", responsible_user_id: "", page: 1, per_page: 25 });
const updateForm = reactive({ status: "", priority: "", responsible_user_id: "", reference_adult_user_id: "", next_review_on: "", closure_reason: "", closure_notes: "", reason: "Actualización del expediente según gestión realizada." });
const causeForm = reactive({ absence_reason_id: "", is_primary: true, information_source: "family", identified_on: new Date().toISOString().slice(0,10), observations: "", is_sensitive: false });
const contactForm = reactive({ contacted_at: new Date().toISOString().slice(0,16), channel: "phone", contacted_person: "", result: "successful", observation: "", next_contact_at: "", responsible_user_id: "" });
const interventionForm = reactive({ intervention_type_id: "", responsible_user_id: "", opened_at: new Date().toISOString().slice(0,16), description: "", result: "", result_summary: "", next_action_at: "", status: "intervention" });
const noteForm = reactive({ note: "", is_sensitive: false });
const agreementForm = reactive({ meeting_date: new Date().toISOString().slice(0,10), agreement: "", responsible_user_id: "", commitment_date: "" });
const planForm = reactive({ initial_situation: "", objective: "", goal_type: "attendance_rate", goal_value: 95, goal_window_days: 30, starts_on: new Date().toISOString().slice(0,10), review_on: "", responsible_user_id: "", actions: [{ title: "Monitorear asistencia semanal", description: "Revisar registros oficiales y contactar ante nuevas ausencias.", frequency: "weekly", due_at: "" }] });
let timer;
const params = computed(() => ({ ...props.filters, ...Object.fromEntries(Object.entries(local).filter(([, value]) => value !== "" && value !== null)) }));
const date = (value, withTime = false) => value ? new Date(value.length <= 10 ? `${value}T12:00:00` : value).toLocaleString("es-CL", withTime ? { dateStyle: "short", timeStyle: "short" } : { dateStyle: "short" }) : "—";
const statusLabel = (value) => (props.configuration.case_statuses || []).find((item) => item.value === value)?.label || String(value || "").replaceAll("_", " ");
const load = async () => { loading.value = true; error.value = ""; try { const { data } = await axios.get("/api/attendance-management/cases", { params: params.value }); rows.value = data.data || []; meta.value = data.meta || {}; } catch (requestError) { error.value = requestError.response?.data?.message || "No fue posible cargar los expedientes."; } finally { loading.value = false; } };
const hydrateUpdate = (item) => Object.assign(updateForm, { status: item.status || "detected", priority: item.priority || "preventive", responsible_user_id: item.responsible_user_id || "", reference_adult_user_id: item.reference_adult_user_id || "", next_review_on: item.next_review_on?.slice(0,10) || "", closure_reason: item.closure_reason || "", closure_notes: item.closure_notes || "", reason: "Actualización del expediente según gestión realizada." });
const openCase = async (id) => { detailLoading.value = true; selected.value = { id }; activeForm.value = ""; try { const { data } = await axios.get(`/api/attendance-management/cases/${id}`); selected.value = data; hydrateUpdate(data); planForm.initial_situation = data.initial_situation || ""; planForm.objective = "Lograr asistencia regular y prevenir nuevas ausencias injustificadas."; planForm.responsible_user_id = data.responsible_user_id || ""; const review = new Date(); review.setDate(review.getDate()+30); planForm.review_on = review.toISOString().slice(0,10); } catch (requestError) { selected.value = null; await showError(requestError, "No se pudo abrir el expediente"); } finally { detailLoading.value = false; } };
const close = () => { selected.value = null; activeForm.value = ""; };
const showError = (requestError, title) => Swal.fire({ icon: "error", title, text: Object.values(requestError.response?.data?.errors || {})[0]?.[0] || requestError.response?.data?.message || "Revisa los datos e intenta nuevamente." });
const refreshSelected = async () => { if (selected.value?.id) await openCase(selected.value.id); await load(); };
const updateCase = async () => { try { const payload = { ...updateForm, responsible_user_id: updateForm.responsible_user_id || null, reference_adult_user_id: updateForm.reference_adult_user_id || null, next_review_on: updateForm.next_review_on || null, closure_reason: updateForm.status === "closed" ? updateForm.closure_reason : null, closure_notes: updateForm.status === "closed" ? updateForm.closure_notes : null }; await axios.patch(`/api/attendance-management/cases/${selected.value.id}`, payload); await refreshSelected(); await success("Expediente actualizado"); } catch (requestError) { await showError(requestError, "No se pudo actualizar"); } };
const submitCause = async () => { try { await axios.post(`/api/attendance-management/cases/${selected.value.id}/causes`, { ...causeForm, absence_reason_id: Number(causeForm.absence_reason_id) }); activeForm.value = ""; await refreshSelected(); await success("Causa registrada"); } catch (requestError) { await showError(requestError, "No se pudo registrar la causa"); } };
const submitContact = async () => { try { await axios.post(`/api/attendance-management/cases/${selected.value.id}/family-contacts`, { ...contactForm, responsible_user_id: contactForm.responsible_user_id || null, next_contact_at: contactForm.next_contact_at || null }); activeForm.value = ""; await refreshSelected(); await success("Contacto familiar registrado"); } catch (requestError) { await showError(requestError, "No se pudo registrar el contacto"); } };
const submitIntervention = async () => { try { await axios.post(`/api/attendance-management/cases/${selected.value.id}/interventions`, { ...interventionForm, intervention_type_id: Number(interventionForm.intervention_type_id), responsible_user_id: interventionForm.responsible_user_id || null, result: interventionForm.result || null, result_summary: interventionForm.result_summary || null, next_action_at: interventionForm.next_action_at || null }); activeForm.value = ""; await refreshSelected(); await success("Intervención registrada"); } catch (requestError) { await showError(requestError, "No se pudo registrar la intervención"); } };
const submitNote = async () => { try { await axios.post(`/api/attendance-management/cases/${selected.value.id}/notes`, noteForm); Object.assign(noteForm, { note: "", is_sensitive: false }); activeForm.value = ""; await refreshSelected(); await success("Nota registrada"); } catch (requestError) { await showError(requestError, "No se pudo registrar la nota"); } };
const submitAgreement = async () => { try { await axios.post(`/api/attendance-management/cases/${selected.value.id}/agreements`, { ...agreementForm, responsible_user_id: agreementForm.responsible_user_id || null, commitment_date: agreementForm.commitment_date || null }); Object.assign(agreementForm, { meeting_date: new Date().toISOString().slice(0,10), agreement: "", responsible_user_id: "", commitment_date: "" }); activeForm.value = ""; await refreshSelected(); await success("Acuerdo registrado"); } catch (requestError) { await showError(requestError, "No se pudo registrar el acuerdo"); } };
const submitPlan = async () => { try { const payload = { ...planForm, goal_value: Number(planForm.goal_value), goal_window_days: Number(planForm.goal_window_days), responsible_user_id: planForm.responsible_user_id || null, actions: planForm.actions.map((action) => ({ ...action, due_at: action.due_at || null, responsible_user_id: planForm.responsible_user_id || null })) }; await axios.post(`/api/attendance-management/cases/${selected.value.id}/action-plans`, payload); activeForm.value = ""; await refreshSelected(); await success("Plan individual creado"); } catch (requestError) { await showError(requestError, "No se pudo crear el plan"); } };
const evaluatePlan = async (plan) => { const result = await Swal.fire({ title: "Evaluar plan", input: "textarea", inputLabel: "Fundamento de la evaluación", inputPlaceholder: "Explica el momento y objetivo de esta evaluación…", showCancelButton: true, confirmButtonText: "Evaluar", cancelButtonText: "Cancelar", inputValidator: (value) => !value?.trim() ? "Ingresa un fundamento." : undefined }); if (!result.isConfirmed) return; try { await axios.post(`/api/attendance-management/action-plans/${plan.id}/evaluate`, { reason: result.value }); await refreshSelected(); await success("Plan evaluado con datos actuales"); } catch (requestError) { await showError(requestError, "No se pudo evaluar el plan"); } };
const updatePlanAction = async (action, status) => { let resultText = action.result || null; if (status === "completed") { const result = await Swal.fire({ title: "Completar acción", input: "textarea", inputLabel: "Resultado verificable", inputValue: action.result || "", showCancelButton: true, confirmButtonText: "Marcar completada", cancelButtonText: "Cancelar", inputValidator: (value) => !value?.trim() ? "Describe el resultado de la acción." : undefined }); if (!result.isConfirmed) return; resultText = result.value; } try { await axios.patch(`/api/attendance-management/action-plan-actions/${action.id}`, { status, result: status === "completed" ? resultText : null, reason: `Cambio de avance de la acción a ${status}.` }); await refreshSelected(); await success("Avance actualizado"); } catch (requestError) { await showError(requestError, "No se pudo actualizar la acción"); } };
const success = (title) => Swal.fire({ icon: "success", title, timer: 1500, showConfirmButton: false });
const addAction = () => planForm.actions.push({ title: "", description: "", frequency: "", due_at: "" });
const scheduleSearch = () => { clearTimeout(timer); timer = setTimeout(() => { local.page=1; load(); }, 350); };
watch(() => [props.filters.academic_year_id, props.filters.course_section_id], () => { local.page=1; load(); });
watch(() => props.initialStatus, (value) => { local.status=value||""; load(); });
onMounted(async () => { await load(); if (props.initialCaseId) openCase(props.initialCaseId); });
defineExpose({ openCase, reload: load, setStatus: (value) => { local.status=value||""; load(); } });
</script>

<template>
  <section class="cases-workspace">
    <div class="case-toolbar"><label class="search"><i class="bx bx-search"></i><input v-model="local.search" type="search" placeholder="Buscar folio, estudiante o RUT" @input="scheduleSearch"></label><label><span>Estado</span><select v-model="local.status" @change="local.page=1;load()"><option value="">Todos los estados</option><option v-for="status in configuration.case_statuses || []" :key="status.value" :value="status.value">{{ status.label }}</option></select></label><label><span>Responsable</span><select v-model="local.responsible_user_id" @change="local.page=1;load()"><option value="">Todos</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><button type="button" class="btn btn-light" @click="Object.assign(local,{search:'',status:'',responsible_user_id:'',page:1});load()"><i class="bx bx-reset"></i>Limpiar</button></div>
    <div class="case-table"><div v-if="error" class="state error"><i class="bx bx-error-circle"></i>{{ error }}</div><div v-else-if="loading && !rows.length" class="state"><span class="spinner-border spinner-border-sm"></span>Cargando expedientes…</div><div v-else class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Expediente</th><th>Estudiante</th><th>Curso</th><th>Estado</th><th>Responsable</th><th>Última gestión</th><th>Próxima revisión</th><th></th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><button type="button" class="folio" @click="openCase(item.id)"><strong>{{ item.folio }}</strong><span>{{ date(item.opened_at) }} · {{ item.priority }}</span></button></td><td><strong>{{ item.student_profile?.registered_name_resolved || item.student_profile?.registered_name || `${item.student_profile?.first_name || ''} ${item.student_profile?.last_name || ''}` }}</strong><span class="muted">{{ item.student_profile?.rut }}</span></td><td>{{ item.course_section?.display_name || 'Sin curso' }}</td><td><span class="status" :class="item.status">{{ statusLabel(item.status) }}</span></td><td>{{ item.responsible?.name || 'Por asignar' }}</td><td>{{ date(item.last_intervention_at, true) }}</td><td><span :class="{ overdue:item.next_review_on && new Date(item.next_review_on)<new Date() }">{{ date(item.next_review_on) }}</span></td><td><button type="button" class="open" @click="openCase(item.id)"><i class="bx bx-chevron-right"></i></button></td></tr><tr v-if="!rows.length"><td colspan="8"><div class="state"><i class="bx bx-folder-open"></i>Sin expedientes para los filtros actuales.</div></td></tr></tbody></table></div><footer><span>{{ meta.total || 0 }} expedientes</span><div><button :disabled="meta.current_page<=1" @click="local.page--;load()"><i class="bx bx-chevron-left"></i></button><span>{{ meta.current_page || 1 }} / {{ meta.last_page || 1 }}</span><button :disabled="meta.current_page>=meta.last_page" @click="local.page++;load()"><i class="bx bx-chevron-right"></i></button></div></footer></div>

    <div v-if="selected" class="modal-layer" @click.self="close"><article class="case-modal"><header><div><span class="eyebrow">EXPEDIENTE TRAZABLE</span><h2>{{ selected.folio || 'Cargando…' }}</h2><p>{{ selected.student_profile?.registered_name_resolved }} · {{ selected.course_section?.display_name }}</p></div><button type="button" @click="close"><i class="bx bx-x"></i></button></header><div v-if="detailLoading" class="modal-loading"><span class="spinner-border"></span></div><template v-else><div class="case-band"><span class="status" :class="selected.status">{{ statusLabel(selected.status) }}</span><div><small>Prioridad</small><strong>{{ selected.priority }}</strong></div><div><small>Responsable</small><strong>{{ selected.responsible?.name || 'Por asignar' }}</strong></div><div><small>Próxima revisión</small><strong>{{ date(selected.next_review_on) }}</strong></div></div><div class="case-actions"><button v-if="capabilities.can_manage_cases" type="button" @click="activeForm=activeForm==='update'?'':'update'"><i class="bx bx-edit"></i>Actualizar</button><button v-if="capabilities.can_manage_cases" type="button" @click="activeForm=activeForm==='note'?'':'note'"><i class="bx bx-note"></i>Nota</button><button v-if="capabilities.can_manage_cases" type="button" @click="activeForm=activeForm==='agreement'?'':'agreement'"><i class="bx bx-handshake"></i>Acuerdo</button><button v-if="capabilities.can_manage_causes" type="button" @click="activeForm=activeForm==='cause'?'':'cause'"><i class="bx bx-search-alt"></i>Causa</button><button v-if="capabilities.can_manage_interventions" type="button" @click="activeForm=activeForm==='contact'?'':'contact'"><i class="bx bx-phone"></i>Contacto</button><button v-if="capabilities.can_manage_interventions" type="button" @click="activeForm=activeForm==='intervention'?'':'intervention'"><i class="bx bx-support"></i>Intervención</button><button v-if="capabilities.can_manage_plans" type="button" @click="activeForm=activeForm==='plan'?'':'plan'"><i class="bx bx-target-lock"></i>Plan de acción</button></div>
          <form v-if="activeForm==='update'" class="action-form" @submit.prevent="updateCase"><h3>Actualizar expediente</h3><div class="form-grid"><label><span>Estado</span><select v-model="updateForm.status"><option v-for="status in configuration.case_statuses || []" :key="status.value" :value="status.value">{{ status.label }}</option></select></label><label><span>Prioridad</span><select v-model="updateForm.priority"><option value="preventive">Preventiva</option><option value="medium">Media</option><option value="high">Alta</option><option value="critical">Crítica</option></select></label><label><span>Responsable</span><select v-model="updateForm.responsible_user_id"><option value="">Por asignar</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Adulto referente</span><select v-model="updateForm.reference_adult_user_id"><option value="">Sin asignar</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Próxima revisión</span><input v-model="updateForm.next_review_on" type="date"></label><label v-if="updateForm.status==='closed'"><span>Motivo de cierre</span><select v-model="updateForm.closure_reason" required><option value="">Seleccionar</option><option value="goal_met">Meta cumplida</option><option value="sustained_improvement">Mejora sostenida</option><option value="student_withdrawal">Retiro</option><option value="school_change">Cambio de establecimiento</option><option value="other">Otro</option></select></label></div><label v-if="updateForm.status==='closed'"><span>Observaciones de cierre</span><textarea v-model="updateForm.closure_notes" rows="2"></textarea></label><label><span>Fundamento de auditoría</span><textarea v-model="updateForm.reason" required rows="2"></textarea></label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form>
          <form v-if="activeForm==='cause'" class="action-form" @submit.prevent="submitCause"><h3>Identificar causa</h3><div class="form-grid"><label><span>Causa</span><select v-model="causeForm.absence_reason_id" required @change="causeForm.is_sensitive=Boolean((configuration.absence_reasons||[]).find(r=>r.id==causeForm.absence_reason_id)?.is_sensitive)"><option value="">Seleccionar</option><option v-for="reason in configuration.absence_reasons || []" :key="reason.id" :value="reason.id">{{ reason.name }}</option></select></label><label><span>Fuente</span><select v-model="causeForm.information_source"><option value="family">Familia</option><option value="student">Estudiante</option><option value="teacher">Docente</option><option value="records">Antecedentes</option><option value="other">Otra</option></select></label><label><span>Fecha de identificación</span><input v-model="causeForm.identified_on" type="date" required></label><label class="check"><input v-model="causeForm.is_primary" type="checkbox">Causa principal</label><label class="check"><input v-model="causeForm.is_sensitive" type="checkbox">Información sensible</label></div><label><span>Observaciones</span><textarea v-model="causeForm.observations" rows="2"></textarea></label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Registrar causa</button></div></form>
          <form v-if="activeForm==='note'" class="action-form" @submit.prevent="submitNote"><h3>Agregar nota al expediente</h3><label><span>Nota de seguimiento</span><textarea v-model="noteForm.note" required rows="3"></textarea></label><label v-if="capabilities.can_view_sensitive" class="check"><input v-model="noteForm.is_sensitive" type="checkbox">Marcar como información sensible</label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Guardar nota</button></div></form>
          <form v-if="activeForm==='agreement'" class="action-form" @submit.prevent="submitAgreement"><h3>Acuerdo de entrevista o reunión</h3><div class="form-grid"><label><span>Fecha de reunión</span><input v-model="agreementForm.meeting_date" type="date" required></label><label><span>Responsable</span><select v-model="agreementForm.responsible_user_id"><option value="">Usuario actual</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Fecha de compromiso</span><input v-model="agreementForm.commitment_date" type="date"></label></div><label><span>Acuerdo verificable</span><textarea v-model="agreementForm.agreement" required rows="3"></textarea></label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Guardar acuerdo</button></div></form>
          <form v-if="activeForm==='contact'" class="action-form" @submit.prevent="submitContact"><h3>Contacto con la familia</h3><div class="form-grid"><label><span>Fecha y hora</span><input v-model="contactForm.contacted_at" type="datetime-local" required></label><label><span>Canal</span><select v-model="contactForm.channel"><option value="phone">Teléfono</option><option value="whatsapp">WhatsApp</option><option value="email">Correo</option><option value="meeting">Entrevista</option><option value="home_visit">Visita domiciliaria</option><option value="other">Otro</option></select></label><label><span>Persona contactada</span><input v-model="contactForm.contacted_person"></label><label><span>Resultado</span><select v-model="contactForm.result"><option value="successful">Contacto efectivo</option><option value="no_answer">Sin respuesta</option><option value="wrong_number">Número incorrecto</option><option value="message_sent">Mensaje enviado</option><option value="meeting_scheduled">Entrevista agendada</option><option value="guardian_reports_cause">Apoderado informa causa</option><option value="other">Otro</option></select></label><label><span>Próximo contacto</span><input v-model="contactForm.next_contact_at" type="datetime-local"></label><label><span>Responsable</span><select v-model="contactForm.responsible_user_id"><option value="">Usuario actual</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label></div><label><span>Registro de la gestión</span><textarea v-model="contactForm.observation" rows="2"></textarea></label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Guardar contacto</button></div></form>
          <form v-if="activeForm==='intervention'" class="action-form" @submit.prevent="submitIntervention"><h3>Registrar intervención</h3><div class="form-grid"><label><span>Tipo</span><select v-model="interventionForm.intervention_type_id" required><option value="">Seleccionar</option><option v-for="type in configuration.intervention_types || []" :key="type.id" :value="type.id">{{ type.name }}</option></select></label><label><span>Responsable</span><select v-model="interventionForm.responsible_user_id"><option value="">Usuario actual</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><label><span>Inicio</span><input v-model="interventionForm.opened_at" type="datetime-local" required></label><label><span>Próxima acción</span><input v-model="interventionForm.next_action_at" type="datetime-local"></label></div><label><span>Descripción</span><textarea v-model="interventionForm.description" required rows="3"></textarea></label><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Guardar intervención</button></div></form>
          <form v-if="activeForm==='plan'" class="action-form" @submit.prevent="submitPlan"><h3>Plan individual de asistencia</h3><label><span>Situación inicial</span><textarea v-model="planForm.initial_situation" required rows="2"></textarea></label><label><span>Objetivo verificable</span><textarea v-model="planForm.objective" required rows="2"></textarea></label><div class="form-grid"><label><span>Indicador meta</span><select v-model="planForm.goal_type"><option value="attendance_rate">Porcentaje de asistencia</option><option value="unjustified_absences">Ausencias injustificadas</option><option value="absence_streak">Racha de ausencias</option></select></label><label><span>Valor meta</span><input v-model.number="planForm.goal_value" type="number" min="0" max="100" step=".1" required></label><label><span>Inicio</span><input v-model="planForm.starts_on" type="date" required></label><label><span>Revisión</span><input v-model="planForm.review_on" type="date" required></label><label><span>Responsable</span><select v-model="planForm.responsible_user_id"><option value="">Responsable del expediente</option><option v-for="user in configuration.assignable_users || []" :key="user.id" :value="user.id">{{ user.name }}</option></select></label></div><div class="actions-editor"><div class="actions-title"><strong>Acciones</strong><button type="button" @click="addAction"><i class="bx bx-plus"></i>Agregar</button></div><div v-for="(action,index) in planForm.actions" :key="index" class="action-row"><input v-model="action.title" required placeholder="Acción verificable"><input v-model="action.frequency" placeholder="Frecuencia"><input v-model="action.due_at" type="datetime-local"><button v-if="planForm.actions.length>1" type="button" @click="planForm.actions.splice(index,1)"><i class="bx bx-trash"></i></button></div></div><div class="form-buttons"><button type="button" class="btn btn-light" @click="activeForm=''">Cancelar</button><button class="btn btn-primary">Crear plan</button></div></form>
          <div v-if="(selected.notes || []).length" class="notes-band"><article v-for="note in selected.notes" :key="note.id"><i class="bx" :class="note.is_sensitive?'bx-lock-alt':'bx-note'"></i><div><strong>{{ note.is_sensitive ? 'Nota sensible' : 'Nota de seguimiento' }}</strong><p>{{ note.note }}</p><small>{{ date(note.created_at,true) }} · {{ note.created_by?.name }}</small></div></article></div>
